const basicFieldsSource = `
import {useForm} from '@tanstack/react-form';
import {Form} from '../../../components/baseui-components/Form';

type BasicFieldValues = {
  fullName: string;
  email: string;
  note: string;
  travelClass: string;
  favoriteCityId: string | null;
  marketingOptIn: boolean;
};

function BasicFieldsExample() {
  const form = useForm<BasicFieldValues>({
    defaultValues: {
      fullName: '',
      email: '',
      note: '',
      travelClass: '',
      favoriteCityId: null,
      marketingOptIn: false,
    },
    onSubmit: async ({value}) => {
      console.log(value);
    },
  });

  return (
    <form onSubmit={(event) => { event.preventDefault(); form.handleSubmit(); }}>
      <form.Field
        name="fullName"
        validators={{
          onChange: ({value}) =>
            value.trim().length >= 2 ? undefined : 'Full name must have at least 2 characters',
        }}
      >
        {(field) => {
          const fieldState = field.state;
          const isInvalid = !fieldState.meta.isValid;
          return (
            <Field.Root name={field.name} invalid={isInvalid}>
              <Field.Label>Full name</Field.Label>
              <Input>
                <Input.Control
                  value={fieldState.value}
                  onBlur={field.handleBlur}
                  onValueChange={field.handleChange}
                />
              </Input>
              <Field.Error match={isInvalid}>{fieldState.meta.errors.join(', ')}</Field.Error>
            </Field.Root>
          );
        }}
      </form.Field>

      <form.Field
        name="travelClass"
        validators={{
          onChange: ({value}) => (value ? undefined : 'Select travel class'),
        }}
      >
        {(field) => {
          const fieldState = field.state;
          return (
            <Field.Root name={field.name} invalid={!fieldState.meta.isValid}>
              <Field.Label>Travel class</Field.Label>
              <RadioGroup
                name={field.name}
                value={fieldState.value}
                onValueChange={(nextValue) => field.handleChange(String(nextValue ?? ''))}
                onBlur={field.handleBlur}
              >
                <Field.Item>
                  <Field.Label inline>
                    <Radio value="economy" />
                    Economy
                  </Field.Label>
                </Field.Item>
                <Field.Item>
                  <Field.Label inline>
                    <Radio value="business" />
                    Business
                  </Field.Label>
                </Field.Item>
              </RadioGroup>
              <Field.Error>{fieldState.meta.errors.join(', ')}</Field.Error>
            </Field.Root>
          );
        }}
      </form.Field>

      <form.Field name="marketingOptIn">
        {(field) => {
          const fieldState = field.state;
          return (
            <Field.Root name={field.name}>
              <Field.Label inline>
                <Checkbox
                  checked={Boolean(fieldState.value)}
                  name={field.name}
                  onBlur={field.handleBlur}
                  onCheckedChange={field.handleChange}
                />
                Receive product updates
              </Field.Label>
            </Field.Root>
          );
        }}
      </form.Field>

      <button type="submit">Submit</button>
    </form>
  );
}
`.trim();
const advancedFieldsSource = `
import {useForm} from '@tanstack/react-form';
import {Form} from '../../../components/baseui-components/Form';

type AdvancedFieldValues = {
  acceptTerms: boolean;
  updatesEnabled: boolean;
  travelClass: string;
  interests: string[];
  cityId: string | null;
  favoriteCityId: string | null;
  visitedCityIds: string[];
  brightness: number;
};

function AdvancedFieldsExample() {
  const form = useForm<AdvancedFieldValues>({
    defaultValues: {
      acceptTerms: false,
      updatesEnabled: false,
      travelClass: '',
      interests: [],
      cityId: null,
      favoriteCityId: null,
      visitedCityIds: [],
      brightness: 25,
    },
    onSubmit: async ({value}) => {
      console.log(value);
    },
  });

  return (
    <form onSubmit={(event) => { event.preventDefault(); form.handleSubmit(); }}>
      <form.Field
        name="acceptTerms"
        validators={{
          onChange: ({value}) => (value ? undefined : 'You must accept terms'),
        }}
      >
        {(field) => {
          const fieldState = field.state;
          const isInvalid = !fieldState.meta.isValid;
          return (
            <Field.Root name={field.name} invalid={isInvalid}>
              <Field.Label inline>
                <Checkbox
                  name={field.name}
                  checked={fieldState.value}
                  onBlur={field.handleBlur}
                  onCheckedChange={field.handleChange}
                />
                I accept terms and conditions
              </Field.Label>
              <Field.Error match={isInvalid}>{fieldState.meta.errors.join(', ')}</Field.Error>
            </Field.Root>
          );
        }}
      </form.Field>

      <form.Field
        name="interests"
        validators={{
          onChange: ({value}) =>
            value.length > 0 ? undefined : 'Select at least one interest',
        }}
      >
        {(field) => {
          const fieldState = field.state;
          const isInvalid = !fieldState.meta.isValid;
          return (
            <Field.Root name={field.name} invalid={isInvalid}>
              <Field.Label>Interests</Field.Label>
              <CheckboxGroup
                value={fieldState.value}
                onValueChange={(nextValue) => field.handleChange(nextValue ?? [])}
              >
                <Field.Item>
                  <Field.Label inline>
                    <Checkbox value="design" />
                    Design
                  </Field.Label>
                </Field.Item>
                <Field.Item>
                  <Field.Label inline>
                    <Checkbox value="engineering" />
                    Engineering
                  </Field.Label>
                </Field.Item>
              </CheckboxGroup>
              <Field.Error match={isInvalid}>{fieldState.meta.errors.join(', ')}</Field.Error>
            </Field.Root>
          );
        }}
      </form.Field>

      <form.Field
        name="brightness"
        validators={{
          onChange: ({value}) => (value >= 10 ? undefined : 'Brightness must be >= 10'),
        }}
      >
        {(field) => {
          const fieldState = field.state;
          const isInvalid = !fieldState.meta.isValid;
          return (
            <Field.Root name={field.name} invalid={isInvalid}>
              <Field.Label>Brightness</Field.Label>
              <Slider.Root
                value={fieldState.value}
                min={0}
                max={100}
                onValueChange={field.handleChange}
              >
                <Slider.Control>
                  <Slider.Track>
                    <Slider.Indicator />
                    <Slider.Thumb />
                  </Slider.Track>
                </Slider.Control>
                <Slider.Value />
              </Slider.Root>
              <Field.Error match={isInvalid}>{fieldState.meta.errors.join(', ')}</Field.Error>
            </Field.Root>
          );
        }}
      </form.Field>

      <button type="submit">Submit</button>
    </form>
  );
}
`.trim();
